import functools
import time


def timed(method):
    @functools.wraps(method)
    def wrapper(self, *args, **kwargs):
        start = time.perf_counter()
        try:
            return method(self, *args, **kwargs)
        finally:
            self.timings.append((method.__name__, time.perf_counter() - start))
    return wrapper


class User:
    def __init__(self):
        self.timings = []

    @timed
    def catalog(self):
        raise RuntimeError("boom")


user = User()
try:
    user.catalog()
except RuntimeError:
    pass
print(len(user.timings), user.timings[0][0])

